// === ESTRUCTURA DEL PATRÓN COMPOSITE ===

// 1. Componente (interfaz común)
abstract class FileSystemComponent {
  constructor(protected name: string) {}

  abstract getSize(): number;
  abstract print(indent?: string): void;

  // Operaciones opcionales que solo los Composite implementan
  add(component: FileSystemComponent): void {
    throw new Error('Cannot add to a leaf node');
  }
  remove(component: FileSystemComponent): void {
    throw new Error('Cannot remove from a leaf node');
  }
}

// 2. Hoja (Leaf)
class File extends FileSystemComponent {
  constructor(name: string, private size: number) {
    super(name);
  }

  getSize(): number {
    return this.size;
  }

  print(indent = ''): void {
    console.log(`${indent}📄 ${this.name} (${this.size}KB)`);
  }
}

// 3. Composite (Compuesto)
class Folder extends FileSystemComponent {
  private children: FileSystemComponent[] = [];

  add(component: FileSystemComponent): void {
    this.children.push(component);
  }

  remove(component: FileSystemComponent): void {
    this.children = this.children.filter(c => c !== component);
  }

  getSize(): number {
    // Suma recursiva de todos los hijos
    return this.children.reduce((total, child) => total + child.getSize(), 0);
  }

  print(indent = ''): void {
    console.log(`${indent}📁 ${this.name}/ (${this.getSize()}KB)`);
    this.children.forEach(child => child.print(indent + '  '));
  }
}

// Uso:
const root = new Folder('proyecto');
const src = new Folder('src');
src.add(new File('index.ts', 5));
src.add(new File('app.ts', 12));
root.add(src);
root.add(new File('package.json', 2));

console.log(root.getSize()); // 19
root.print();

