// Interfaz unificada — hojas y composites responden igual
abstract class FileSystemComponent {
  abstract getSize(): number;
}

class File extends FileSystemComponent {
  constructor(private name: string, private size: number) { super(); }
  getSize() { return this.size; }
}

class Folder extends FileSystemComponent {
  private children: FileSystemComponent[] = [];
  add(child: FileSystemComponent) { this.children.push(child); }
  getSize() {
    return this.children.reduce((sum, child) => sum + child.getSize(), 0);
  }
}

// El cliente no distingue entre archivo y carpeta
const root = new Folder('root');
root.add(new File('readme.md', 2));
const src = new Folder('src');
src.add(new File('app.ts', 10));
root.add(src);
console.log(root.getSize()); // 12

